const CONVERTED_TITLE = /^converted from references\.md \(/;
export const elementIdOf = (id) => String(id).replace(/\//g, '-');
export const fileOfId = (id) => `${elementIdOf(id)}.md`;
export const idOfFile = (name) => name.replace(/\.md$/, '');

